import React from 'react';
import './MenuForms.css';

const MenuForms = ({ userId }) => {
    const scrollToInfo = () => {
        const infoSection = document.getElementById('info-section');
        if (infoSection) {
            infoSection.scrollIntoView({ behavior: 'smooth' });
        }
    };

    return (
        <div className="menu-form">
            <h2>Opciones</h2>
            <div className="menu-options">
                <div className="saving-box" onClick={scrollToInfo}>
                    <div className="icon">💰</div>
                    <span>Generar Ahorro</span>
                </div>
                <div className="saving-box" onClick={scrollToInfo}>
                    <div className="icon">📈</div>
                    <span>Plan de Jubilación</span>
                </div>
                <div className="saving-box" onClick={scrollToInfo}>
                    <div className="icon">🎯</div>
                    <span>Metas Largo/Corto Plazo</span>
                </div>
            </div>

            {/* Sección de información */}
            <div id="info-section" className="info-section">
                <h3>Información sobre Generar Ahorro</h3>
                <p>Aquí puedes encontrar información útil sobre cómo generar ahorros efectivos...</p>
                {/* Puedes añadir más información relevante aquí */}
            </div>
        </div>
    );
};

export default MenuForms;
